﻿app.factory('dataAjax',
    function($http) {

        var getCount = 0;
        return {
            ajaxGet: function(url, successFunction, data, showLoading) {
                if (showLoading && showLoading == true) {
                    if (getCount == 0) {
                        $('.site-loader-bg').css("visibility", "visible");
                        $('.site-loader-box').css("visibility", "visible");
                    }

                    getCount++;
                }
                $http.get(url, { params: data }).then(function(msg) { //success
                        if (successFunction) {
                            successFunction(msg.data);
                        }
                    })
                    .then(function() { //complete
                        if (showLoading && showLoading == true) {
                            getCount--;
                            if (getCount == 0) {
                                $('.site-loader-bg').css("visibility", "hidden");
                                $('.site-loader-box').css("visibility", "hidden");
                            }
                        }
                    });
            },

            ajaxPost: function(url, successFunction, data, showLoading) {
                if (showLoading && showLoading == true) {
                    $('.site-loader-bg').css("visibility", "visible");
                    $('.site-loader-box').css("visibility", "visible");
                }
                $http.post(url, JSON.stringify(data)).then(function(msg) { //success
                    if (successFunction) {
                        if (showLoading && showLoading == true) {
                            $('.site-loader-bg').css("visibility", "hidden");
                            $('.site-loader-box').css("visibility", "hidden");
                        }

                        successFunction(msg.data);
                    }
                }).then(function() { //complete
                });
            }
        };
    });

