﻿app.controller('BlogSearchController', [
    '$scope', '$element', 'blogDataRepository', function($scope, $element, blogDataRepository) {
        //$($element).hide();
        //$($element).css("opacity", 0);
        $scope.loadCompeleted = false;
        $scope.searchKeyword = '';

        $scope.blogCategories = new Array();
        $scope.selectedBlogCategoryIDs = new Array();

        $scope.ageRanges = new Array();
        $scope.selectedAgeRangeIDs = new Array();

        $scope.blogContentTypes = new Array();
        $scope.selectedBlogContentTypeIDs = new Array();

        $scope.blogTags = new Array();
        $scope.selectedBlogTagIDs = new Array();

        $scope.blogPostSortTypes = new Array();
        $scope.selectedBlogPostSortTypeID = "1";

        $scope.availablePageSizes = ["12", "24", "36", "48"];
        $scope.selectedPageSize = "12";

        $scope.visiblePages = new Array();
        $scope.selectedPagingGroup = 1;
        $scope.pagingGroupSize = 10;
        $scope.totalPageCount = 0;
        $scope.selectedPage = 1;

        $scope.noDataExists = true;

        $scope.searchKeyword = blogDataRepository.getSearchKeyword();
        $scope.selectedBlogPostSortTypeID = blogDataRepository.getSelectedBlogPostSortTypeID();
        blogDataRepository.loadBlogCategories($scope.blogCategories, $scope.selectedBlogCategoryIDs);
        blogDataRepository.loadAgeRanges($scope.ageRanges, $scope.selectedAgeRangeIDs);
        blogDataRepository.loadBlogContentTypes($scope.blogContentTypes, $scope.selectedBlogContentTypeIDs);
        blogDataRepository.loadBlogTags($scope.blogTags, $scope.selectedBlogTagIDs);
        blogDataRepository.loadBlogPostSortTypes($scope.blogPostSortTypes);

        $scope.$watch('blogCategories',
            function(newVal, oldVal, scope) {
                if ($scope.loadCompeleted != true) {
                    return;
                }
                scope.selectedBlogCategoryIDs.length = 0;
                for (var i = 0; newVal && i < newVal.length; i++) {
                    if (newVal[i].Checked == true) {
                        scope.selectedBlogCategoryIDs.push(newVal[i].ID);
                    }
                }

                scope.selectedPage = 1;
                scope.doSearch();
            },
            true);
        $scope.$watch('ageRanges',
            function(newVal, oldVal, scope) {
                if ($scope.loadCompeleted != true) {
                    return;
                }
                scope.selectedAgeRangeIDs.length = 0;
                for (var i = 0; newVal && i < newVal.length; i++) {
                    if (newVal[i].Checked == true) {
                        scope.selectedAgeRangeIDs.push(newVal[i].ID);
                    }
                }

                scope.selectedPage = 1;
                scope.doSearch();
            },
            true);
        $scope.$watch('blogContentTypes',
            function(newVal, oldVal, scope) {
                if ($scope.loadCompeleted != true) {
                    return;
                }
                scope.selectedBlogContentTypeIDs.length = 0;
                for (var i = 0; newVal && i < newVal.length; i++) {
                    if (newVal[i].Checked == true) {
                        scope.selectedBlogContentTypeIDs.push(newVal[i].ID);
                    }
                }

                scope.selectedPage = 1;
                scope.doSearch();
            },
            true);
        $scope.$watch('blogTags',
            function(newVal, oldVal, scope) {
                if ($scope.loadCompeleted != true) {
                    return;
                }
                scope.selectedBlogTagIDs.length = 0;
                for (var i = 0; newVal && i < newVal.length; i++) {
                    if (newVal[i].Checked == true) {
                        scope.selectedBlogTagIDs.push(newVal[i].ID);
                    }
                }

                scope.selectedPage = 1;
                scope.doSearch();
            },
            true);

        $scope.$watch('selectedBlogPostSortTypeID',
            function(newVal, oldVal, scope) {
                if ($scope.loadCompeleted != true) {
                    return;
                }
                if (newVal != oldVal) {
                    scope.doSearch();
                }
            },
            true);
        $scope.$watch('selectedPage',
            function(newVal, oldVal, scope) {
                if ($scope.loadCompeleted != true) {
                    return;
                }
                if (newVal != oldVal) {
                    scope.doSearch();
                }
            },
            true);
        $scope.$watch('selectedPageSize',
            function(newVal, oldVal, scope) {
                if ($scope.loadCompeleted != true) {
                    return;
                }
                if (newVal != oldVal) {
                    scope.selectedPage = 1;
                    scope.doSearch();
                }
            },
            true);

        $scope.$watch('totalPageCount',
            function(newVal, oldVal, scope) {
                if ($scope.loadCompeleted != true) {
                    return;
                }
                if (newVal != oldVal) {
                    scope.noDataExists = (newVal == 0);
                }
            },
            true);

        $scope.doSearch = function() {
            blogDataRepository.BlogSearch($scope.searchResultPresent,
                $scope.selectedPageSize,
                $scope.selectedPage,
                $scope.searchKeyword,
                $scope.selectedBlogCategoryIDs,
                $scope.selectedAgeRangeIDs,
                $scope.selectedBlogContentTypeIDs,
                $scope.selectedBlogTagIDs,
                $scope.selectedBlogPostSortTypeID);
        };

        $scope.searchResultPresent = $.proxy(function(data) {
                $('#blog-search-result-container').html(data.html);

                AppScript.initImageContextMenuPrevention();

                this.visiblePages.length = 0;
                this.totalPageCount = data.pageCount;
                for (var i = ((this.selectedPagingGroup - 1) * this.pagingGroupSize); i < data.pageCount; i++) {
                    this.visiblePages.push(i + 1);
                    if (i + 1 == this.selectedPagingGroup * this.pagingGroupSize) {
                        break;
                    }
                }
            },
            $scope);

        $scope.doSearch();

        $element.ready(function () {

            $scope.loadCompeleted = true;
            $($element).animate({
                    opacity: 1
                },
                2000,
                function() {
                    $($element).css({ 'min-height': '' });
                });
            $($element).show();

            setTimeout(function () {
                $().onlyXLines({
                    selector: ".blog-post-list-item1 .blog-post-list-item-details-area .blog-post-list-item-lead p",
                });
            }, 1000);
        });


        $scope.changeSelectedPage = function(item) {
            $scope.selectedPage = item;
        };
        $scope.getActiveClass = function(item) {
            if (item == $scope.selectedPage) {
                return 'active';
            }
            return '';
        };
        $scope.nextStyle = function() {
            if ($scope.selectedPagingGroup > 1) {
                return "prev";
            }
            return "prev hide";
        };

        $scope.preStyle = function() {
            if ($scope.PageCount > ($scope.selectedPagingGroup * $scope.pagingGroupSize)) {
                return "next";
            }
            return "next hide";
        };

        $scope.prevPageGroup = function() {
            $scope.selectedPagingGroup--;
            $scope.selectedPage = (($scope.selectedPagingGroup - 1) * $scope.pagingGroupSize) + 1;
        };

        $scope.nextPageGroup = function() {
            $scope.selectedPagingGroup++;
            $scope.selectedPage = (($scope.selectedPagingGroup - 1) * $scope.pagingGroupSize) + 1;
        };
    }
]);
